//! COBJMACROS dispatch helpers, per arch. Generated by tools/gen_commacros.py from the
//! bindgen island — do not edit by hand. Regenerate with:
//!
//!   for a in i386 amd64 arm64; do tools/gen_commacros.py \
//!       --bindgen sdk/lib/rust/recyclebin-rust/src/types_$a.rs \
//!       -o sdk/lib/rust/recyclebin-rust/src/commacros_$a.rs \
//!       --only IRecycleBin,IRecycleBin5,IRecycleBinEnumList,IRecycleBinFile; done
//!
//! recyclebin.h defines `IRecycleBin_DeleteFile(This, x)` and friends as
//! `(This)->lpVtbl->DeleteFile(This, x)`. rustconv reproduces the call site verbatim, which
//! is right — but nothing then supplies the callee, so every one was an unresolved name.
//! Per arch is not optional: a slot whose PARAMETER is itself a function pointer carries
//! that callback's calling convention in its type, and bindgen spells it per arch.
#[cfg(target_arch = "x86")]
#[path = "commacros_i386.rs"]
mod commacros_arch;
#[cfg(target_arch = "x86_64")]
#[path = "commacros_amd64.rs"]
mod commacros_arch;
#[cfg(target_arch = "aarch64")]
#[path = "commacros_arm64.rs"]
mod commacros_arch;
pub use commacros_arch::*;
